"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[15371],{13001(e,a,o){o.r(a),o.d(a,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"cursos/cleancode/modulos/nombres-significativos/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es la \\"Smurf Naming Convention\\" (o Smurf Code) y por qu\xe9 es considerada un anti-patr\xf3n que va m\xe1s all\xe1 de lo que la clase describe como \\"nombres ruido\\"?","source":"@site/docs/cursos/cleancode/modulos/02-nombres-significativos/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/02-nombres-significativos","slug":"/cursos/cleancode/modulos/nombres-significativos/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/nombres-significativos/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/nombres-significativos/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/nombres-significativos/ejercicio"}}');var n=o(74848),r=o(28453);const i={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,l={},d=[{value:"2. [Investigar] \xbfQu\xe9 es la &quot;Smurf Naming Convention&quot; (o Smurf Code) y por qu\xe9 es considerada un anti-patr\xf3n que va m\xe1s all\xe1 de lo que la clase describe como &quot;nombres ruido&quot;?",id:"2-investigar-qu\xe9-es-la-smurf-naming-convention-o-smurf-code-y-por-qu\xe9-es-considerada-un-anti-patr\xf3n-que-va-m\xe1s-all\xe1-de-lo-que-la-clase-describe-como-nombres-ruido",level:3},{value:"3. [Investigar] \xbfQu\xe9 dice la investigaci\xf3n en psicolog\xeda cognitiva sobre la &quot;longitud \xf3ptima&quot; de un identificador? \xbfQu\xe9 estudios existen \u2014m\xe1s all\xe1 de las opiniones de Martin y Ottinger\u2014 sobre la relaci\xf3n entre longitud de nombres y comprensi\xf3n de c\xf3digo?",id:"3-investigar-qu\xe9-dice-la-investigaci\xf3n-en-psicolog\xeda-cognitiva-sobre-la-longitud-\xf3ptima-de-un-identificador-qu\xe9-estudios-existen-m\xe1s-all\xe1-de-las-opiniones-de-martin-y-ottinger-sobre-la-relaci\xf3n-entre-longitud-de-nombres-y-comprensi\xf3n-de-c\xf3digo",level:3},{value:"4. [Investigar] \xbfQu\xe9 es la &quot;Phil Karlton&#39;s Quote&quot; que menciona que hay dos problemas dif\xedciles en computaci\xf3n? \xbfQu\xe9 investigaciones y patrones han surgido para atacar el problema del naming desde aproximaciones sistem\xe1ticas?",id:"4-investigar-qu\xe9-es-la-phil-karltons-quote-que-menciona-que-hay-dos-problemas-dif\xedciles-en-computaci\xf3n-qu\xe9-investigaciones-y-patrones-han-surgido-para-atacar-el-problema-del-naming-desde-aproximaciones-sistem\xe1ticas",level:3},{value:"5. [Conectar] La clase menciona que se debe evitar la notaci\xf3n h\xfangara. \xbfQu\xe9 distingue exactamente la &quot;Systems Hungarian&quot; de la &quot;Apps Hungarian&quot; seg\xfan la aclaraci\xf3n que hizo el propio Charles Simonyi? \xbfEn qu\xe9 contexto la Apps Hungarian S\xcd podr\xeda ser beneficiosa?",id:"5-conectar-la-clase-menciona-que-se-debe-evitar-la-notaci\xf3n-h\xfangara-qu\xe9-distingue-exactamente-la-systems-hungarian-de-la-apps-hungarian-seg\xfan-la-aclaraci\xf3n-que-hizo-el-propio-charles-simonyi-en-qu\xe9-contexto-la-apps-hungarian-s\xed-podr\xeda-ser-beneficiosa",level:3},{value:"6. [Conectar] La clase establece que &quot;las clases deben ser sustantivos y los m\xe9todos verbos&quot;. \xbfC\xf3mo manejan esta regla los patrones de dise\xf1o que usan nombres de clase que son verbos? \xbfQu\xe9 dice la comunidad sobre excepciones como <code>Validator</code>, <code>Builder</code>, <code>Observer</code>?",id:"6-conectar-la-clase-establece-que-las-clases-deben-ser-sustantivos-y-los-m\xe9todos-verbos-c\xf3mo-manejan-esta-regla-los-patrones-de-dise\xf1o-que-usan-nombres-de-clase-que-son-verbos-qu\xe9-dice-la-comunidad-sobre-excepciones-como-validator-builder-observer",level:3},{value:"7. [Conectar] La clase recomienda usar nombres pronunciables y buscables. \xbfQu\xe9 desaf\xedos de naming presentan los sistemas que operan en m\xfaltiples idiomas (ej. c\xf3digo en ingl\xe9s pero dominio de negocio en espa\xf1ol)? \xbfQu\xe9 recomienda Eric Evans en DDD para estos casos?",id:"7-conectar-la-clase-recomienda-usar-nombres-pronunciables-y-buscables-qu\xe9-desaf\xedos-de-naming-presentan-los-sistemas-que-operan-en-m\xfaltiples-idiomas-ej-c\xf3digo-en-ingl\xe9s-pero-dominio-de-negocio-en-espa\xf1ol-qu\xe9-recomienda-eric-evans-en-ddd-para-estos-casos",level:3},{value:"8. [Cuestionar] La clase afirma que nombres como <code>Manager</code>, <code>Handler</code>, <code>Processor</code> son &quot;banderas rojas&quot;. Sin embargo, el ecosistema Spring est\xe1 poblado de estos nombres (<code>RequestMappingHandlerAdapter</code>, <code>AnnotationProcessor</code>). \xbfSon estos nombres intr\xednsecamente malos o hay contextos donde son precisamente lo que se necesita? \xbfQu\xe9 m\xe9trica objetiva usar\xedas para decidir?",id:"8-cuestionar-la-clase-afirma-que-nombres-como-manager-handler-processor-son-banderas-rojas-sin-embargo-el-ecosistema-spring-est\xe1-poblado-de-estos-nombres-requestmappinghandleradapter-annotationprocessor-son-estos-nombres-intr\xednsecamente-malos-o-hay-contextos-donde-son-precisamente-lo-que-se-necesita-qu\xe9-m\xe9trica-objetiva-usar\xedas-para-decidir",level:3},{value:"9. [Cuestionar] La clase recomienda evitar prefijos <code>I</code> para interfaces y <code>Impl</code> para implementaciones. \xbfQu\xe9 argumentan los defensores de estos prefijos (por ejemplo, la Java Core Library usa <code>List</code>/<code>ArrayList</code>, no <code>IList</code>/<code>List</code>)? \xbfEn qu\xe9 tipo de proyectos tener una \xfanica implementaci\xf3n <code>Interface</code> + <code>InterfaceImpl</code> S\xcd podr\xeda ser un smell de dise\xf1o?",id:"9-cuestionar-la-clase-recomienda-evitar-prefijos-i-para-interfaces-y-impl-para-implementaciones-qu\xe9-argumentan-los-defensores-de-estos-prefijos-por-ejemplo-la-java-core-library-usa-listarraylist-no-ilistlist-en-qu\xe9-tipo-de-proyectos-tener-una-\xfanica-implementaci\xf3n-interface--interfaceimpl-s\xed-podr\xeda-ser-un-smell-de-dise\xf1o",level:3},{value:"10. [Cuestionar] La clase dice que nombres de una letra &quot;solo sirven en scopes muy cortos&quot;. \xbfQu\xe9 posici\xf3n defienden los lenguajes funcionales y la comunidad matem\xe1tica de la programaci\xf3n sobre nombres cortos vs. largos en contextos de alta abstracci\xf3n? \xbfHay escuelas de pensamiento que DEFIENDEN nombres cortos como virtud?",id:"10-cuestionar-la-clase-dice-que-nombres-de-una-letra-solo-sirven-en-scopes-muy-cortos-qu\xe9-posici\xf3n-defienden-los-lenguajes-funcionales-y-la-comunidad-matem\xe1tica-de-la-programaci\xf3n-sobre-nombres-cortos-vs-largos-en-contextos-de-alta-abstracci\xf3n-hay-escuelas-de-pensamiento-que-defienden-nombres-cortos-como-virtud",level:3}];function t(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-la-smurf-naming-convention-o-smurf-code-y-por-qu\xe9-es-considerada-un-anti-patr\xf3n-que-va-m\xe1s-all\xe1-de-lo-que-la-clase-describe-como-nombres-ruido",children:'2. [Investigar] \xbfQu\xe9 es la "Smurf Naming Convention" (o Smurf Code) y por qu\xe9 es considerada un anti-patr\xf3n que va m\xe1s all\xe1 de lo que la clase describe como "nombres ruido"?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': La Smurf Naming Convention es un anti-patr\xf3n descrito por la comunidad donde un prefijo o sufijo se repite en TODAS o casi todas las clases de un m\xf3dulo, como los Pitufos (Smurfs) que anteponen "pitufo\u2014 a todo. Ejemplo: ',(0,n.jsx)(a.code,{children:"SmurfOrderValidator"}),", ",(0,n.jsx)(a.code,{children:"SmurfOrderProcessor"}),", ",(0,n.jsx)(a.code,{children:"SmurfOrderRepository"}),", ",(0,n.jsx)(a.code,{children:"SmurfOrderService"}),'. El problema va m\xe1s all\xe1 del ruido: (a) rompe la capacidad de autocompletado del IDE (escribir "Order" deber\xeda mostrar todas las clases relacionadas con \xf3rdenes, pero con el prefijo "Smurf" primero aparece todo lo dem\xe1s que empiece con S), (b) oculta las verdaderas relaciones sem\xe1nticas entre clases (\xbf',(0,n.jsx)(a.code,{children:"SmurfOrder"})," tiene m\xe1s en com\xfan con ",(0,n.jsx)(a.code,{children:"SmurfUser"})," \u2014por el prefijo\u2014 o con ",(0,n.jsx)(a.code,{children:"Order"})," \u2014por el concepto? La respuesta es con ",(0,n.jsx)(a.code,{children:"Order"}),", pero el prefijo sugiere lo contrario), (c) es un s\xedntoma de que el equipo intent\xf3 resolver con naming un problema de namespace/packaging."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase advierte sobre sufijos como ",(0,n.jsx)(a.code,{children:"Info"}),", ",(0,n.jsx)(a.code,{children:"Data"}),", ",(0,n.jsx)(a.code,{children:"Manager"}),' pero no sobre la Smurf Naming Convention. Este anti-patr\xf3n es end\xe9mico en proyectos Java enterprise (donde todo lleva el prefijo del proyecto) y en microservicios (donde todo lleva el nombre del servicio). La soluci\xf3n no es un mejor nombre sino mejor estructura: packages y m\xf3dulos para agrupar por concepto, no prefijos. Fuentes: "Smurf Naming" se discute en Code Complete 2, en blogs de la comunidad, y en el contexto de Java naming conventions de Google y Oracle.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-qu\xe9-dice-la-investigaci\xf3n-en-psicolog\xeda-cognitiva-sobre-la-longitud-\xf3ptima-de-un-identificador-qu\xe9-estudios-existen-m\xe1s-all\xe1-de-las-opiniones-de-martin-y-ottinger-sobre-la-relaci\xf3n-entre-longitud-de-nombres-y-comprensi\xf3n-de-c\xf3digo",children:'3. [Investigar] \xbfQu\xe9 dice la investigaci\xf3n en psicolog\xeda cognitiva sobre la "longitud \xf3ptima" de un identificador? \xbfQu\xe9 estudios existen \u2014m\xe1s all\xe1 de las opiniones de Martin y Ottinger\u2014 sobre la relaci\xf3n entre longitud de nombres y comprensi\xf3n de c\xf3digo?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': El estudio cl\xe1sico es "The Impact of Identifier Style on Comprehension" (Binkley et al., 2009, ICPC), que encontr\xf3 que identificadores con palabras completas (ej. ',(0,n.jsx)(a.code,{children:"numberOfEmployees"}),") se comprenden significativamente m\xe1s r\xe1pido que abreviaturas (",(0,n.jsx)(a.code,{children:"noEmp"}),") o letras sueltas (",(0,n.jsx)(a.code,{children:"n"}),'). Sin embargo, estudios posteriores matizaron esto. "To CamelCase or Under_score" (Binkley, 2009) encontr\xf3 que en lenguajes que usan camelCase, nombres de hasta 20-25 caracteres siguen siendo r\xe1pidos de procesar; pasando las 30 caracteres, el tiempo de lectura aumenta. Un estudio m\xe1s reciente de Hofmeister et al. (2017, ESEM) encontr\xf3 que la relaci\xf3n NO es lineal: nombres extremadamente cortos (1-3 chars) y extremadamente largos (m\xe1s de 30 chars) son lentos de comprender. El "punto dulce" medido est\xe1 entre 8 y 20 caracteres, similar a las palabras del lenguaje natural. M\xe1s interesante: el estudio encontr\xf3 que nombres que siguen la estructura gramatical que el lector espera (verbo-sustantivo para m\xe9todos, sustantivo-adjetivo para clases) se entienden M\xc1S R\xc1PIDO que nombres m\xe1s cortos pero que rompen esa expectativa.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase da recomendaciones basadas en la experiencia de Martin y Ottinger pero sin evidencia emp\xedrica. Conocer los estudios de Binkley y Hofmeister permite argumentar con datos, no solo con autoridad. Por ejemplo: "la clase dice que no hay que temer nombres largos si clarifican, pero Hofmeister sugiere que pasando 30 caracteres, la comprensi\xf3n se degrada". Esto da profundidad al criterio del alumno.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-la-phil-karltons-quote-que-menciona-que-hay-dos-problemas-dif\xedciles-en-computaci\xf3n-qu\xe9-investigaciones-y-patrones-han-surgido-para-atacar-el-problema-del-naming-desde-aproximaciones-sistem\xe1ticas",children:'4. [Investigar] \xbfQu\xe9 es la "Phil Karlton\'s Quote" que menciona que hay dos problemas dif\xedciles en computaci\xf3n? \xbfQu\xe9 investigaciones y patrones han surgido para atacar el problema del naming desde aproximaciones sistem\xe1ticas?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Phil Karlton, ingeniero de Netscape, es famoso por la frase: "There are only two hard things in Computer Science: cache invalidation and naming things." (luego se a\xf1adi\xf3 humor\xedsticamente "and off-by-one errors"). La dificultad del naming ha generado aproximaciones sistem\xe1ticas: (a) Arnaoudova et al. (2015, en su tesis doctoral y publicaciones) crearon un cat\xe1logo ling\xfc\xedstico de "Linguistic Anti-Patterns": violaciones donde el nombre contradice la implementaci\xf3n (ej. un m\xe9todo llamado ',(0,n.jsx)(a.code,{children:"isAvailable"}),' que LANZA excepci\xf3n en lugar de retornar booleano; un getter que modifica estado), (b) El proyecto Naturalize (Allamanis et al., 2015, Microsoft Research) aplic\xf3 modelos estad\xedsticos de lenguaje natural al c\xf3digo fuente para detectar nombres "an\xf3malos" que no siguen los patrones estad\xedsticos del resto del proyecto, (c) H\xf8st y \xd8stvold (2009) identificaron que la inconsistencia de naming entre verbo y implementaci\xf3n es una fuente significativa de bugs: m\xe9todos ',(0,n.jsx)(a.code,{children:"get*"})," que hacen side effects son m\xe1s bug-prone que m\xe9todos ",(0,n.jsx)(a.code,{children:"get*"})," que son consultas puras."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase enfoca el naming como un arte basado en reglas heur\xedsticas. Las investigaciones de Arnaoudova y Allamanis convierten el naming en ciencia medible: no es solo "me gusta" o "no me gusta", hay patrones cuantificables y herramientas (Naturalize, LINGUA) que pueden detectar violaciones autom\xe1ticamente. Esto lleva el naming m\xe1s all\xe1 de los consejos de Clean Code a un \xe1rea de investigaci\xf3n activa en ingenier\xeda de software emp\xedrica.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-que-se-debe-evitar-la-notaci\xf3n-h\xfangara-qu\xe9-distingue-exactamente-la-systems-hungarian-de-la-apps-hungarian-seg\xfan-la-aclaraci\xf3n-que-hizo-el-propio-charles-simonyi-en-qu\xe9-contexto-la-apps-hungarian-s\xed-podr\xeda-ser-beneficiosa",children:'5. [Conectar] La clase menciona que se debe evitar la notaci\xf3n h\xfangara. \xbfQu\xe9 distingue exactamente la "Systems Hungarian" de la "Apps Hungarian" seg\xfan la aclaraci\xf3n que hizo el propio Charles Simonyi? \xbfEn qu\xe9 contexto la Apps Hungarian S\xcd podr\xeda ser beneficiosa?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Charles Simonyi, creador de la notaci\xf3n h\xfangara en Microsoft, aclar\xf3 en su art\xedculo "Hungarian Notation" (1999) que \xe9l cre\xf3 DOS variantes: (a) "Systems Hungarian": codifica el TIPO de dato (',(0,n.jsx)(a.code,{children:"lpszName"}),", ",(0,n.jsx)(a.code,{children:"dwFlags"}),", ",(0,n.jsx)(a.code,{children:"iCount"}),'), y es la que se populariz\xf3 (incorrectamente) y la que Clean Code critica con raz\xf3n \u2014el IDE ya conoce los tipos, el prefijo es redundante y se desactualiza. (b) "Apps Hungarian": codifica el PROP\xd3SITO o dominio, no el tipo. Por ejemplo: ',(0,n.jsx)(a.code,{children:"xMargin"})," vs ",(0,n.jsx)(a.code,{children:"yMargin"})," (ambos son ",(0,n.jsx)(a.code,{children:"int"})," pero representan m\xe1rgenes en ejes distintos), ",(0,n.jsx)(a.code,{children:"cbName"})," (count of bytes del nombre) vs ",(0,n.jsx)(a.code,{children:"cchName"})," (count of characters). Simonyi argumenta que Apps Hungarian previene bugs donde us\xe1s un ",(0,n.jsx)(a.code,{children:"int"})," que representa pulgadas donde se esperaba uno que representa cent\xedmetros, porque los prefijos ",(0,n.jsx)(a.code,{children:"in"})," y ",(0,n.jsx)(a.code,{children:"cm"})," lo hacen visible. Esta distinci\xf3n fue enterrada por la popularizaci\xf3n incorrecta de Systems Hungarian."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase condena la notaci\xf3n h\xfangara sin distinguir las variantes. La Apps Hungarian tiene defensores incluso hoy: Joel Spolsky (cofundador de Stack Overflow y ex-Microsoft) escribi\xf3 "Making Wrong Code Look Wrong" (2005, joelonsoftware.com) defendiendo Apps Hungarian. Spolsky argumenta que en lenguajes sin tipos fuertes (JavaScript, Python) o al trabajar con tipos primitivos que representan distintas magnitudes, Apps Hungarian hace visible la sem\xe1ntica que el sistema de tipos no puede capturar. El alumno debe entender que no toda "codificaci\xf3n en el nombre" es igualmente mala.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"6-conectar-la-clase-establece-que-las-clases-deben-ser-sustantivos-y-los-m\xe9todos-verbos-c\xf3mo-manejan-esta-regla-los-patrones-de-dise\xf1o-que-usan-nombres-de-clase-que-son-verbos-qu\xe9-dice-la-comunidad-sobre-excepciones-como-validator-builder-observer",children:['6. [Conectar] La clase establece que "las clases deben ser sustantivos y los m\xe9todos verbos". \xbfC\xf3mo manejan esta regla los patrones de dise\xf1o que usan nombres de clase que son verbos? \xbfQu\xe9 dice la comunidad sobre excepciones como ',(0,n.jsx)(a.code,{children:"Validator"}),", ",(0,n.jsx)(a.code,{children:"Builder"}),", ",(0,n.jsx)(a.code,{children:"Observer"}),"?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": La clase recomienda sustantivos para clases, pero m\xfaltiples patrones del Gang of Four (Design Patterns, 1994) usan nombres de clase basados en verbos o roles activos: ",(0,n.jsx)(a.code,{children:"Builder"}),", ",(0,n.jsx)(a.code,{children:"Observer"}),", ",(0,n.jsx)(a.code,{children:"Decorator"}),", ",(0,n.jsx)(a.code,{children:"Visitor"}),", ",(0,n.jsx)(a.code,{children:"Command"}),", ",(0,n.jsx)(a.code,{children:"Strategy"}),". La comunidad ha reconciliado esto de dos formas: (1) Los patrones nombran el ROL que la clase desempe\xf1a, no la clase en s\xed. Cuando implement\xe1s el patr\xf3n, la clase se llama ",(0,n.jsx)(a.code,{children:"HtmlReportBuilder"})," (sustantivo + rol), no solo ",(0,n.jsx)(a.code,{children:"Builder"}),'. (2) Estos nombres son "agent nouns" en ingl\xe9s: palabras que terminan en -er, -or que indican "el que hace X". Gramaticalmente son SUSTANTIVOS derivados de verbos. ',(0,n.jsx)(a.code,{children:"Validator"}),' es "el que valida" \u2014es un sustantivo, no un verbo. La regla de Clean Code deber\xeda refinarse: las clases deben ser sustantivos o "nombres de agente", no verbos en infinitivo o imperativo. ',(0,n.jsx)(a.code,{children:"Validate"})," (verbo) es mal nombre de clase; ",(0,n.jsx)(a.code,{children:"Validator"})," (nombre de agente) es aceptable."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase da la regla de manera binaria (sustantivos = clases, verbos = m\xe9todos), lo cual es demasiado simplista y genera confusi\xf3n cuando los alumnos encuentran patrones de dise\xf1o. El GoF es lectura fundamental y el alumno debe entender que la regla es una heur\xedstica, no una ley. La ling\xfc\xedstica detr\xe1s de "agent nouns" (Milkov et al., 2016, en el contexto de NLP aplicado a c\xf3digo) muestra que estos nombres ocupan un espacio intermedio y son naturalmente comprendidos por desarrolladores.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"7-conectar-la-clase-recomienda-usar-nombres-pronunciables-y-buscables-qu\xe9-desaf\xedos-de-naming-presentan-los-sistemas-que-operan-en-m\xfaltiples-idiomas-ej-c\xf3digo-en-ingl\xe9s-pero-dominio-de-negocio-en-espa\xf1ol-qu\xe9-recomienda-eric-evans-en-ddd-para-estos-casos",children:"7. [Conectar] La clase recomienda usar nombres pronunciables y buscables. \xbfQu\xe9 desaf\xedos de naming presentan los sistemas que operan en m\xfaltiples idiomas (ej. c\xf3digo en ingl\xe9s pero dominio de negocio en espa\xf1ol)? \xbfQu\xe9 recomienda Eric Evans en DDD para estos casos?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Los sistemas multiling\xfces enfrentan un dilema: \xbfusar los t\xe9rminos del dominio en el idioma del negocio (espa\xf1ol) o traducirlos al ingl\xe9s (idioma del c\xf3digo)? Eric Evans en DDD (2003, cap\xedtulo 2) y la comunidad de DDD moderna recomiendan: usar el lenguaje del negocio EN el c\xf3digo cuando el t\xe9rmino NO tiene una traducci\xf3n precisa o cuando la traducci\xf3n introduce ambig\xfcedad. Ejemplo: si el negocio habla de "retenci\xf3n en la fuente", traducirlo a "withholdingTax" puede ser aceptable si el equipo es biling\xfce y el t\xe9rmino ingl\xe9s es preciso. Pero t\xe9rminos como "monotributista" en Argentina NO tienen equivalente exacto en ingl\xe9s; usar "SimplifiedRegimeTaxpayer" oscurece el dominio. Clean Code NO aborda el multiling\xfcismo porque asume que todo se escribe en ingl\xe9s.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Esto es relevante porque el curso se dicta en Sudamericana, en contexto hispanohablante. Los alumnos trabajar\xe1n en sistemas donde el dominio est\xe1 en espa\xf1ol pero el c\xf3digo usa palabras en ingl\xe9s. La recomendaci\xf3n de Evans (usar el ubiquitous language, que puede ser multiling\xfce si el negocio lo es) complementa la regla de "una palabra por concepto" de Clean Code con la dimensi\xf3n cultural. Tambi\xe9n plantea el conflicto: \xbfqu\xe9 pasa si la palabra en espa\xf1ol no es pronunciable para un desarrollador angloparlante que se una al equipo? El alumno debe desarrollar criterio.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"8-cuestionar-la-clase-afirma-que-nombres-como-manager-handler-processor-son-banderas-rojas-sin-embargo-el-ecosistema-spring-est\xe1-poblado-de-estos-nombres-requestmappinghandleradapter-annotationprocessor-son-estos-nombres-intr\xednsecamente-malos-o-hay-contextos-donde-son-precisamente-lo-que-se-necesita-qu\xe9-m\xe9trica-objetiva-usar\xedas-para-decidir",children:["8. [Cuestionar] La clase afirma que nombres como ",(0,n.jsx)(a.code,{children:"Manager"}),", ",(0,n.jsx)(a.code,{children:"Handler"}),", ",(0,n.jsx)(a.code,{children:"Processor"}),' son "banderas rojas". Sin embargo, el ecosistema Spring est\xe1 poblado de estos nombres (',(0,n.jsx)(a.code,{children:"RequestMappingHandlerAdapter"}),", ",(0,n.jsx)(a.code,{children:"AnnotationProcessor"}),"). \xbfSon estos nombres intr\xednsecamente malos o hay contextos donde son precisamente lo que se necesita? \xbfQu\xe9 m\xe9trica objetiva usar\xedas para decidir?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Los nombres con sufijo de rol NO son intr\xednsecamente malos; lo es usarlos para EVITAR pensar en un nombre m\xe1s preciso. En Spring, nombres como ",(0,n.jsx)(a.code,{children:"BeanFactoryPostProcessor"})," son precisos: describen exactamente qu\xe9 hace la clase en el ciclo de vida de Spring, y son nombres heredados de patrones de dise\xf1o predecibles. La diferencia es: (a) en Spring, el sufijo tiene sem\xe1ntica contractual (un Processor de Spring tiene un contrato espec\xedfico, comportamiento esperado y posici\xf3n en una cadena), (b) en c\xf3digo de negocio, ",(0,n.jsx)(a.code,{children:"OrderProcessor"}),' suele significar "no s\xe9 bien qu\xe9 hace esta clase, pero hace algo con \xf3rdenes". La m\xe9trica objetiva es el "test de responsabilidad \xfanica": \xbfpod\xe9s describir la responsabilidad de la clase sin usar el sufijo? Si ',(0,n.jsx)(a.code,{children:"OrderManager"}),' es "manages orders" (circular), el nombre falla. Si ',(0,n.jsx)(a.code,{children:"BeanPostProcessor"}),' es "permite modificar beans despu\xe9s de su inicializaci\xf3n" (definici\xf3n concreta y testeable), el nombre es v\xe1lido.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase presenta los sufijos de rol como code smells sin matices. Esto genera confusi\xf3n cuando los alumnos trabajan con Spring, donde estos nombres son omnipresentes y correctos. Robert Martin discute esto en su blog: la diferencia es si el sufijo aporta informaci\xf3n de dominio o es un comod\xedn para "no s\xe9 c\xf3mo nombrar esto". El alumno debe desarrollar la capacidad de distinguir cu\xe1ndo un ',(0,n.jsx)(a.code,{children:"Processor"})," es un patr\xf3n leg\xedtimo y cu\xe1ndo es pereza mental."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"9-cuestionar-la-clase-recomienda-evitar-prefijos-i-para-interfaces-y-impl-para-implementaciones-qu\xe9-argumentan-los-defensores-de-estos-prefijos-por-ejemplo-la-java-core-library-usa-listarraylist-no-ilistlist-en-qu\xe9-tipo-de-proyectos-tener-una-\xfanica-implementaci\xf3n-interface--interfaceimpl-s\xed-podr\xeda-ser-un-smell-de-dise\xf1o",children:["9. [Cuestionar] La clase recomienda evitar prefijos ",(0,n.jsx)(a.code,{children:"I"})," para interfaces y ",(0,n.jsx)(a.code,{children:"Impl"})," para implementaciones. \xbfQu\xe9 argumentan los defensores de estos prefijos (por ejemplo, la Java Core Library usa ",(0,n.jsx)(a.code,{children:"List"}),"/",(0,n.jsx)(a.code,{children:"ArrayList"}),", no ",(0,n.jsx)(a.code,{children:"IList"}),"/",(0,n.jsx)(a.code,{children:"List"}),")? \xbfEn qu\xe9 tipo de proyectos tener una \xfanica implementaci\xf3n ",(0,n.jsx)(a.code,{children:"Interface"})," + ",(0,n.jsx)(a.code,{children:"InterfaceImpl"})," S\xcd podr\xeda ser un smell de dise\xf1o?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": La Java Core Library no usa ",(0,n.jsx)(a.code,{children:"I"}),"/",(0,n.jsx)(a.code,{children:"Impl"}),". ",(0,n.jsx)(a.code,{children:"List"})," es la interfaz, ",(0,n.jsx)(a.code,{children:"ArrayList"})," y ",(0,n.jsx)(a.code,{children:"LinkedList"})," son implementaciones con nombres que comunican su ESTRATEGIA (",(0,n.jsx)(a.code,{children:"Array"}),"-backed, ",(0,n.jsx)(a.code,{children:"Linked"}),"-list). Este es el est\xe1ndar que Clean Code defiende: el nombre de la implementaci\xf3n revela POR QU\xc9 existe separada de la interfaz. Los defensores de ",(0,n.jsx)(a.code,{children:"I"}),"/",(0,n.jsx)(a.code,{children:"Impl"})," (com\xfan en proyectos C# pre-.NET Core y en Java enterprise legacy) aducen que: (a) hace expl\xedcito qu\xe9 clases son interfaces sin necesidad de IDE, (b) en codebases grandes con cientos de interfaces, el prefijo agrupa visualmente. Sin embargo, ",(0,n.jsx)(a.code,{children:"Interface"})," + ",(0,n.jsx)(a.code,{children:"InterfaceImpl"})," ES un smell cuando solo hay UNA implementaci\xf3n y nunca habr\xe1 m\xe1s: \xbfpara qu\xe9 la interfaz entonces? O la interfaz no se justifica (YAGNI) o el nombre ",(0,n.jsx)(a.code,{children:"Impl"})," no comunica el PROP\xd3SITO de esa implementaci\xf3n espec\xedfica. Pattern: si solo ten\xe9s una implementaci\xf3n, o la interfaz sobra, o la implementaci\xf3n merece un nombre mejor que ",(0,n.jsx)(a.code,{children:"Impl"}),"."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase da una regla ("no uses I/Impl") sin discutir el contexto. En .NET Framework, ',(0,n.jsx)(a.code,{children:"I"}),'-prefijo era el est\xe1ndar de Microsoft hasta hace poco, y millones de l\xedneas de c\xf3digo lo usan. La discusi\xf3n no deber\xeda ser "qu\xe9 prefijo es malo" sino "cu\xe1ndo necesito una interfaz y c\xf3mo nombro su implementaci\xf3n para comunicar intenci\xf3n". El alumno debe entender que ',(0,n.jsx)(a.code,{children:"Impl"})," es una oportunidad perdida de comunicar dise\xf1o."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"10-cuestionar-la-clase-dice-que-nombres-de-una-letra-solo-sirven-en-scopes-muy-cortos-qu\xe9-posici\xf3n-defienden-los-lenguajes-funcionales-y-la-comunidad-matem\xe1tica-de-la-programaci\xf3n-sobre-nombres-cortos-vs-largos-en-contextos-de-alta-abstracci\xf3n-hay-escuelas-de-pensamiento-que-defienden-nombres-cortos-como-virtud",children:'10. [Cuestionar] La clase dice que nombres de una letra "solo sirven en scopes muy cortos". \xbfQu\xe9 posici\xf3n defienden los lenguajes funcionales y la comunidad matem\xe1tica de la programaci\xf3n sobre nombres cortos vs. largos en contextos de alta abstracci\xf3n? \xbfHay escuelas de pensamiento que DEFIENDEN nombres cortos como virtud?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": S\xed, hay al menos dos escuelas que defienden nombres cortos. (1) La tradici\xf3n de programaci\xf3n funcional (Haskell, ML) y matem\xe1tica: en expresiones puras y composici\xf3n de funciones, nombres como ",(0,n.jsx)(a.code,{children:"f"}),", ",(0,n.jsx)(a.code,{children:"g"}),", ",(0,n.jsx)(a.code,{children:"x"}),", ",(0,n.jsx)(a.code,{children:"xs"})," son preferibles porque la operaci\xf3n ES la sem\xe1ntica. ",(0,n.jsx)(a.code,{children:"map f xs"})," es m\xe1s legible que ",(0,n.jsx)(a.code,{children:"applyFunctionToEachElementOfList functionToApply listOfInputElements"})," \u2014la brevedad revela que no hay side effects, que la operaci\xf3n es gen\xe9rica, y que solo importa la firma de tipos. (2) La escuela APL/K/J (Kenneth Iverson): donde el lenguaje mismo es simb\xf3lico y los programas se expresan como composiciones de operadores; poner nombres largos oscurecer\xeda la estructura. En contextos de programaci\xf3n de arrays y finanzas cuantitativas, esta escuela tiene defensores. La clave para reconciliar: la longitud del nombre debe ser proporcional al SCOPE y a la ESPECIFICIDAD del dominio. Una variable local ",(0,n.jsx)(a.code,{children:"i"})," en un loop de 3 l\xedneas es correcta; un par\xe1metro ",(0,n.jsx)(a.code,{children:"x"})," en una funci\xf3n ",(0,n.jsx)(a.code,{children:"square(x) = x * x"})," es correcto porque la funci\xf3n es matem\xe1tica y el tipo lo dice todo."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase da la regla desde la perspectiva exclusiva de OOP empresarial Java. Pero el alumno que sale de este curso podr\xeda trabajar con Scala, Kotlin, Clojure o Python, donde las convenciones de naming son diferentes. La comunidad Haskell valora la brevedad y genericidad de nombres; la comunidad Java valora la expresividad. Entender que no hay UNA respuesta correcta y que la elecci\xf3n depende del paradigma y el contexto es parte de la madurez t\xe9cnica que el curso busca evaluar. Fuente: "Haskell Programming from First Principles" (Allen & Moronuki, 2015), "Notation as a Tool of Thought" (Ken Iverson, 1979, Turing Award Lecture).']})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(t,{...e})}):t(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>c});var s=o(96540);const n={},r=s.createContext(n);function i(e){const a=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),s.createElement(r.Provider,{value:a},e.children)}}}]);